#include <random>
#include <vector>
#include <cmath>

struct vec3 {
    double x, y, z;
    vec3() : x(0), y(0), z(0) {}
    vec3(double x, double y, double z) : x(x), y(y), z(z) {}
};

void applyAndersonThermostat(std::vector<vec3>& velocities, const std::vector<double>& masses, double targetTemp, double collisionFreq, double dt) {
    // Create random number generator
    std::mt19937 rng(std::random_device{}());

    // For each particle
    for (size_t i = 0; i < velocities.size(); ++i) {
        // Check if collision occurs based on collision frequency and timestep
        double collisionProbability = collisionFreq * dt;
        std::uniform_real_distribution<double> uniformDist(0.0, 1.0);

        if (uniformDist(rng) < collisionProbability) {
            // Calculate standard deviation for Maxwell-Boltzmann distribution
            // Assuming kB = 1 (normalized units)
            double stdDev = std::sqrt(targetTemp / masses[i]);

            // Create normal distribution for velocity components
            std::normal_distribution<double> normalDist(0.0, stdDev);

            // Assign new random velocity components
            velocities[i].x = normalDist(rng);
            velocities[i].y = normalDist(rng);
            velocities[i].z = normalDist(rng);
        }
    }
}

