void applyAndersonThermostat(std::vector<vec3>& velocities, const std::vector<double>& masses, double targetTemp, double collisionFreq, double dt) {
    // Use static to preserve state between calls
    static std::mt19937 generator;
    static bool initialized = false;

    if (!initialized) {
        generator.seed(std::random_device{}());
        initialized = true;
    }

    // For each particle
    for (size_t i = 0; i < velocities.size(); ++i) {
        // Calculate collision probability
        double collisionProbability = collisionFreq * dt;

        // Generate uniform random number between 0 and 1
        std::uniform_real_distribution<double> uniformDist(0.0, 1.0);

        if (uniformDist(generator) < collisionProbability) {
            // Calculate standard deviation for Maxwell-Boltzmann distribution
            // Assuming Boltzmann constant = 1 (normalized units)
            double stdDev = std::sqrt(targetTemp / masses[i]);

            // Generate normally distributed random numbers for each velocity component
            std::normal_distribution<double> normalDist(0.0, stdDev);

            // Assign new random velocity components
            velocities[i].x = normalDist(generator);
            velocities[i].y = normalDist(generator);
            velocities[i].z = normalDist(generator);
        }
    }
}

